const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0; const pending = new Map(); const logs = [];
ws.addEventListener("message", (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); return; }
  if (msg.method === "Runtime.consoleAPICalled") logs.push(`${msg.params.type}: ${msg.params.args.map((a) => a.value ?? a.description).join(" ")}`);
  if (msg.method === "Runtime.exceptionThrown") logs.push(`exception: ${msg.params.exceptionDetails.exception?.description ?? msg.params.exceptionDetails.text}`);
  if (msg.method === "Log.entryAdded") logs.push(`log ${msg.params.entry.level}: ${msg.params.entry.text}`);
});
const send = (method, params = {}) => new Promise((res, rej) => { const i = ++id; pending.set(i, (m) => m.error ? rej(new Error(`${method}: ${m.error.message}`)) : res(m.result)); ws.send(JSON.stringify({ id: i, method, params })); });
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const shot = async (name) => { const { data } = await send("Page.captureScreenshot", { format: "png" }); const p = `${dir}${label}-${mode}-${name}.png`; writeFileSync(p, Buffer.from(data, "base64")); console.log(p); };
const inkCount = () => send("Runtime.evaluate", { expression: `(() => { const c = document.querySelector('canvas'); const g = c.getContext('2d'); const d = g.getImageData(0,0,c.width,c.height).data; let n=0; for (let i=0;i<d.length;i+=4) if (d[i+3]>0) n++; return n; })()`, returnByValue: true }).then((r) => r.result.value);
await send("Runtime.enable"); await send("Log.enable"); await send("Page.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 820, height: 1180, deviceScaleFactor: 2, mobile: true });
if (mode === "touch") await send("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 5 });
await send("Page.navigate", { url: "http://127.0.0.1:5173/b/tap-repro-" + Date.now() });
await wait(2500);
const stroke = async (y0) => {
  const pts = Array.from({ length: 12 }, (_, i) => ({ x: 150 + i * 40, y: y0 + Math.sin(i / 2) * 30 }));
  if (mode === "touch") {
    await send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [{ ...pts[0], id: 1 }] });
    for (const p of pts.slice(1)) { await send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: [{ ...p, id: 1 }] }); await wait(16); }
    return async () => send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
  }
  await send("Input.dispatchMouseEvent", { type: "mousePressed", ...pts[0], button: "left", buttons: 1, clickCount: 1 });
  for (const p of pts.slice(1)) { await send("Input.dispatchMouseEvent", { type: "mouseMoved", ...p, button: "left", buttons: 1 }); await wait(16); }
  return async () => send("Input.dispatchMouseEvent", { type: "mouseReleased", ...pts.at(-1), button: "left", buttons: 0, clickCount: 1 });
};
await shot("0-empty");
const lift1 = await stroke(400); await wait(100); await lift1(); await wait(300);
console.log("ink after stroke 1:", await inkCount()); await shot("1-first-stroke");
const lift2 = await stroke(700); await wait(100);
console.log("ink during stroke 2:", await inkCount()); await shot("2-during-second");
await lift2(); await wait(300);
console.log("ink after stroke 2:", await inkCount()); await shot("3-after-second");
console.log("console:", logs.length ? logs.join("\n") : "(none)");
await fetch(`http://localhost:9222/json/close/${target.id}`);
process.exit(0);
EOF
