export const TILE_SIZE = 256;
export const MIN_LEVEL = -40;
export const MAX_LEVEL = 40;
export const LIVE_TILE_MIN_PX = 64;
export const SUB_PIXEL_PX = 1;
import fc from "fast-check";
import { describe, expect, test } from "vitest";
import {
  contains,
  fromTileLocal,
  isSubPixel,
  MAX_LEVEL,
  MIN_LEVEL,
  nativeLevel,
  place,
  tileBounds,
  tileKey,
  tileScreenSize,
  toTileLocal,
  viewTiles,
} from "./index";
const bbox = (minX: number, minY: number, w: number, h: number) => ({
  minX,
  minY,
  maxX: minX + w,
  maxY: minY + h,
});
describe("tiles", () => {
  test("native tiles are between 256 and 512 px on screen", () => {
    for (const zoom of [1, 0.3, 3, 2 ** -20, 1000]) {
      const px = tileScreenSize(nativeLevel(zoom), zoom);
      expect(px).toBeGreaterThanOrEqual(256);
      expect(px).toBeLessThan(512);
    }
  });
  test("native level clamps to the level range", () => {
    expect(nativeLevel(2 ** 60)).toBe(MIN_LEVEL);
    expect(nativeLevel(2 ** -60)).toBe(MAX_LEVEL);
  });
  test("keys and tile-local coordinates round-trip", () => {
    const tile = { level: -3, tx: -5, ty: 7 };
    expect(tileKey(tile)).toBe("-3:-5:7");
    const point = { x: -155, y: 230 };
    expect(fromTileLocal(tile, toTileLocal(tile, point))).toEqual(point);
  });
});
describe("placement", () => {
  test("uses the smallest tile that fits", () => {
    expect(place(bbox(10, 10, 100, 100))).toEqual({ ok: true, tile: { level: -1, tx: 0, ty: 0 } });
  });
  test("bumps a bbox that straddles a boundary to a coarser level", () => {
    const placed = place(bbox(250, 10, 10, 10));
    expect(placed).toEqual({ ok: true, tile: { level: 1, tx: 0, ty: 0 } });
  });
  test("places a bbox across the origin in the root tile", () => {
    expect(place(bbox(-1, -1, 2, 2))).toEqual({
      ok: true,
      tile: { level: MAX_LEVEL, tx: 0, ty: 0 },
    });
  });
  test("the placement tile holds the whole bbox", () => {
    fc.assert(
      fc.property(
        fc.double({ min: -1e9, max: 1e9, noNaN: true }),
        fc.double({ min: -1e9, max: 1e9, noNaN: true }),
        fc.double({ min: 0, max: 1e6, noNaN: true }),
        fc.double({ min: 0, max: 1e6, noNaN: true }),
        (x, y, w, h) => {
          const box = bbox(x, y, w, h);
          const placed = place(box);
          return placed.ok && contains(tileBounds(placed.tile), box);
        },
      ),
    );
  });
  test("the coarser bump terminates within the level range", () => {
    fc.assert(
      fc.property(
        fc.double({ min: -1e300, max: 1e300, noNaN: true }),
        fc.double({ min: -1e300, max: 1e300, noNaN: true }),
        fc.double({ min: 0, max: 1e300, noNaN: true }),
        (x, y, w) => {
          const placed = place(bbox(x, y, w, w));
          return !placed.ok || placed.tile.level <= MAX_LEVEL;
        },
      ),
    );
  });
});
describe("view", () => {
  const zoom = 1;
  const view = viewTiles({ minX: 0, minY: 0, maxX: 1024, maxY: 768 }, zoom);
  test("splits levels into a live band and a snapshot band down to the pixel cutoff", () => {
    expect(view.native).toBe(0);
    expect(view.live.at(0)?.level).toBe(MAX_LEVEL);
    expect(view.live.at(-1)?.level).toBe(-2);
    expect(view.snapshot.map((r) => r.level)).toEqual([-3, -4, -5, -6, -7, -8]);
    expect(view.live.find((r) => r.level === 0)).toEqual({
      level: 0,
      minTx: 0,
      minTy: 0,
      maxTx: 4,
      maxTy: 3,
    });
  });
  test("every visible object lands in a queried tile", () => {
    const ranges = [...view.live, ...view.snapshot];
    for (const box of [bbox(1000, 700, 2, 2), bbox(-50, -50, 100, 100), bbox(500, 500, 1e6, 3)]) {
      const placed = place(box);
      if (!placed.ok) throw new Error("placement overflowed");
      const { level, tx, ty } = placed.tile;
      const range = ranges.find((r) => r.level === level);
      expect(range).toBeDefined();
      expect(tx).toBeGreaterThanOrEqual(range?.minTx ?? Infinity);
      expect(tx).toBeLessThanOrEqual(range?.maxTx ?? -Infinity);
      expect(ty).toBeGreaterThanOrEqual(range?.minTy ?? Infinity);
      expect(ty).toBeLessThanOrEqual(range?.maxTy ?? -Infinity);
    }
  });
  test("culls objects below one pixel", () => {
    expect(isSubPixel(bbox(0, 0, 0.5, 0.5), zoom)).toBe(true);
    expect(isSubPixel(bbox(0, 0, 0.5, 0.5), 4)).toBe(false);
  });
});
export * from "./constants";
export * from "./placement";
export * from "./tile";
export * from "./view";
import { MAX_LEVEL, MIN_LEVEL, TILE_SIZE } from "./constants";
import { type BBox, contains, type Tile, tileAt, tileBounds } from "./tile";
export type Placement = { ok: true; tile: Tile } | { ok: false; reason: "Overflow" };
function startLevel(bbox: BBox): number {
  const extent = Math.max(bbox.maxX - bbox.minX, bbox.maxY - bbox.minY);
  if (!(extent > 0)) return MIN_LEVEL;
  return Math.min(MAX_LEVEL, Math.max(MIN_LEVEL, Math.ceil(Math.log2(extent / TILE_SIZE))));
}
export function place(bbox: BBox): Placement {
  for (let level = startLevel(bbox); level <= MAX_LEVEL; level++) {
    const tile = tileAt(level, { x: bbox.minX, y: bbox.minY });
    if (contains(tileBounds(tile), bbox)) return { ok: true, tile };
  }
  return { ok: false, reason: "Overflow" };
}
import { MAX_LEVEL, MIN_LEVEL, TILE_SIZE } from "./constants";
export type Point = { x: number; y: number };
export type BBox = { minX: number; minY: number; maxX: number; maxY: number };
export type Tile = { level: number; tx: number; ty: number };
export function clampLevel(level: number): number {
  return Math.min(MAX_LEVEL, Math.max(MIN_LEVEL, level)) + 0;
}
export function tileWorldSize(level: number): number {
  return TILE_SIZE * 2 ** level;
}
export function gridOrigin(level: number): number {
  return level === MAX_LEVEL ? -tileWorldSize(MAX_LEVEL) / 2 : 0;
}
export function tileScreenSize(level: number, zoom: number): number {
  return tileWorldSize(level) * zoom;
}
export function nativeLevel(zoom: number): number {
  if (!(zoom > 0) || !Number.isFinite(zoom)) {
    throw new RangeError(`zoom must be a positive finite number, got ${zoom}`);
  }
  return clampLevel(Math.ceil(-Math.log2(zoom)));
}
export function tileIndex(level: number, coordinate: number): number {
  return Math.floor((coordinate - gridOrigin(level)) / tileWorldSize(level)) + 0;
}
export function tileAt(level: number, point: Point): Tile {
  return { level, tx: tileIndex(level, point.x), ty: tileIndex(level, point.y) };
}
function tileMin(level: number, index: number): number {
  return gridOrigin(level) + index * tileWorldSize(level);
}
export function tileBounds(tile: Tile): BBox {
  return {
    minX: tileMin(tile.level, tile.tx),
    minY: tileMin(tile.level, tile.ty),
    maxX: tileMin(tile.level, tile.tx + 1),
    maxY: tileMin(tile.level, tile.ty + 1),
  };
}
export function tileKey(tile: Tile): string {
  return `${tile.level}:${tile.tx}:${tile.ty}`;
}
export function coarser(tile: Tile): Tile {
  const bounds = tileBounds(tile);
  return tileAt(tile.level + 1, { x: bounds.minX, y: bounds.minY });
}
export function toTileLocal(tile: Tile, point: Point): Point {
  const size = tileWorldSize(tile.level);
  return {
    x: ((point.x - tileMin(tile.level, tile.tx)) / size) * TILE_SIZE,
    y: ((point.y - tileMin(tile.level, tile.ty)) / size) * TILE_SIZE,
  };
}
export function fromTileLocal(tile: Tile, local: Point): Point {
  const size = tileWorldSize(tile.level);
  return {
    x: tileMin(tile.level, tile.tx) + (local.x / TILE_SIZE) * size,
import type { LevelRange, Tile } from "@stallion/geometry";
import { decode, encode, type StallionObject } from "@stallion/schema";
import { type DBSchema, type IDBPDatabase, type IDBPObjectStore, openDB } from "idb";

export type StoredObject = { tile: Tile; object: StallionObject };

type TileRecord = {
  boardId: string;
  level: number;
  tx: number;
  ty: number;
  objectId: string;
  bytes: Uint8Array;
};

type TileKey = [string, number, number, number, string];

interface StallionDB extends DBSchema {
  objects: { key: TileKey; value: TileRecord };
}

type ObjectStore = IDBPObjectStore<StallionDB, ["objects"], "objects", "readonly">;

const DB_NAME = "stallion";
const DB_VERSION = 1;

const openStallionDB = (): Promise<IDBPDatabase<StallionDB>> =>
  openDB<StallionDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      db.createObjectStore("objects", { keyPath: ["boardId", "level", "tx", "ty", "objectId"] });
    },
  });

export type BoardStore = {
  put(stored: StoredObject): Promise<void>;
  query(ranges: readonly LevelRange[]): Promise<StoredObject[]>;
  close(): void;
};

export async function openBoardStore(boardId: string): Promise<BoardStore> {
  const db = await openStallionDB();

  const put = async ({ tile, object }: StoredObject): Promise<void> => {
    await db.put("objects", {
      boardId,
      level: tile.level,
      tx: tile.tx,
      ty: tile.ty,
      objectId: object.objectId,
      bytes: encode(object),
    });
  };

  const queryLevel = async (store: ObjectStore, range: LevelRange): Promise<StoredObject[]> => {
    const keys = IDBKeyRange.bound(
      [boardId, range.level, range.minTx],
      [boardId, range.level, range.maxTx, []],
    );
    const records = await store.getAll(keys);
    return records.flatMap((record) => {
      if (record.ty < range.minTy || record.ty > range.maxTy) return [];
      const decoded = decode(record.bytes);
      if (!decoded.ok) {
        throw new TypeError(`Stored object ${record.objectId} is invalid: ${decoded.error}`);
      }
      return [
        { tile: { level: record.level, tx: record.tx, ty: record.ty }, object: decoded.value },
      ];
    });
  };

  const query = async (ranges: readonly LevelRange[]): Promise<StoredObject[]> => {
    const tx = db.transaction("objects", "readonly");
    const results = await Promise.all(ranges.map((range) => queryLevel(tx.store, range)));
    await tx.done;
    return results.flat();
  };

  return { put, query, close: () => db.close() };
}

